package com.bank.comparison.service;

import com.bank.comparison.dto.ComparisonReport;
import com.bank.comparison.model.Trade;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.*;

@Service
@Slf4j
public class ComparisonService {

    private final List<Trade> trades = List.of(
        new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED"),
        new Trade("TRD-002", "TCS", new BigDecimal("176000"), "SETTLED"),
        new Trade("TRD-003", "HDFC", new BigDecimal("330150"), "PENDING"),
        new Trade("TRD-004", "INFY", new BigDecimal("222037"), "SETTLED")
    );

    public ComparisonReport compare() {

        // ═══ COLLECTION capabilities — CRUD, size, index, reuse ═══
        Map<String, String> collectionOps = new LinkedHashMap<>();

        collectionOps.put("size", "trades.size() = " + trades.size());
        collectionOps.put("get_by_index", "trades.get(0) = " + trades.get(0).tradeId());
        collectionOps.put("contains", "trades.contains(TRD-001) = searchable");
        collectionOps.put("reusable", "Can iterate trades 100 times — always works");
        collectionOps.put("mutable", "ArrayList: add(), remove(), set() — modify in place");

        // Reuse proof:
        long count1 = 0; for (Trade t : trades) if (t.isSettled()) count1++;
        long count2 = 0; for (Trade t : trades) if (t.isSettled()) count2++;
        collectionOps.put("reuse_proof", "Iterated twice: " + count1 + " and " + count2 + " — both work");

        // ═══ STREAM capabilities — transform, aggregate, parallel ═══
        Map<String, String> streamOps = new LinkedHashMap<>();

        // Stream has NO size(), NO get(), NO contains()
        streamOps.put("no_size", "Stream has no size() — unknown until terminal");
        streamOps.put("no_get", "Stream has no get(index) — no random access");
        streamOps.put("no_contains", "Stream has no contains() — no membership test");

        // But stream excels at:
        BigDecimal total = trades.stream()
            .filter(Trade::isSettled)
            .map(Trade::amount)
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        streamOps.put("filter_map_reduce", "Settled total = Rs." + total);

        Map<String, Long> grouped = trades.stream()
            .collect(Collectors.groupingBy(Trade::status, Collectors.counting()));
        streamOps.put("grouping", "By status: " + grouped);

        String csv = trades.stream()
            .map(Trade::symbol).distinct().sorted()
            .collect(Collectors.joining(", "));
        streamOps.put("transform_join", "Symbols: " + csv);

        streamOps.put("single_use", "Stream consumed after terminal — IllegalStateException on reuse");
        streamOps.put("parallel", "trades.parallelStream() — built-in ForkJoinPool");
        streamOps.put("lazy", "filter+map NOT executed until terminal (collect/reduce) called");

        // ═══ KEY DIFFERENCES ═══
        List<String> differences = List.of(
            "1. STORAGE: Collection=stores elements | Stream=stores nothing (pipeline)",
            "2. EVAL: Collection=eager (all in memory) | Stream=lazy (on demand)",
            "3. REUSE: Collection=unlimited iterations | Stream=one-time only",
            "4. MUTATION: Collection=add/remove/set | Stream=immutable pipeline",
            "5. SIZE: Collection=size() known | Stream=no size(), unknown until terminal",
            "6. ITERATION: Collection=external (you control) | Stream=internal (stream controls)",
            "7. PARALLEL: Collection=manual threads | Stream=parallelStream() built-in"
        );

        return new ComparisonReport(collectionOps, streamOps, differences);
    }
}
```

