// ─── File: src/test/java/com/bank/comparison/service/StreamVsCollectionTest.java ───
package com.bank.comparison.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class StreamVsCollectionTest {

    @Test
    void collectionHasSizeStreamDoesNot() {
        List<String> list = List.of("A", "B", "C");
        assertThat(list.size()).isEqualTo(3);  // Collection: size() (Recommended) 

        // Stream: no size() method
        // Stream.of("A", "B", "C").size();  // COMPILE ERROR!
        // Must use terminal: stream.count()
        assertThat(Stream.of("A", "B", "C").count()).isEqualTo(3);
    }

    @Test
    void collectionIsReusableStreamIsNot() {
        List<String> list = List.of("A", "B");
        assertThat(list.stream().count()).isEqualTo(2);  // use 1
        assertThat(list.stream().count()).isEqualTo(2);  // use 2 — OK!

        Stream<String> stream = Stream.of("A", "B");
        stream.count();
        assertThatThrownBy(() -> stream.count())
            .isInstanceOf(IllegalStateException.class);
    }

    @Test
    void collectionIsMutableStreamIsNot() {
        List<String> list = new ArrayList<>(List.of("A", "B"));
        list.add("C");        // (Recommended) mutable
        list.remove("A");     // (Recommended) mutable
        assertThat(list).containsExactly("B", "C");

        // Stream: no add(), no remove()
        // Produces NEW data, never modifies source
        List<String> filtered = list.stream().filter(s -> !s.equals("B")).toList();
        assertThat(list).containsExactly("B", "C");        // source unchanged!
        assertThat(filtered).containsExactly("C");          // new list
    }

    @Test
    void collectionIsEagerStreamIsLazy() {
        // Collection: all elements exist immediately
        List<String> list = List.of("A", "B", "C");  // 3 elements in memory NOW

        // Stream: lazy — nothing until terminal
        var counter = new java.util.concurrent.atomic.AtomicInteger(0);
        Stream<String> lazy = list.stream()
            .filter(s -> { counter.incrementAndGet(); return true; });

        assertThat(counter.get()).isZero();  // LAZY — nothing executed!
        lazy.toList();                         // terminal triggers
        assertThat(counter.get()).isEqualTo(3);
    }

    @Test
    void collectionSupportsRandomAccessStreamDoesNot() {
        List<String> list = List.of("RELIANCE", "TCS", "HDFC");
        assertThat(list.get(1)).isEqualTo("TCS");  // random access (Recommended) 

        // Stream: no get(index)
        // Must use skip+findFirst as workaround
        String second = Stream.of("RELIANCE", "TCS", "HDFC")
            .skip(1).findFirst().orElse("");
        assertThat(second).isEqualTo("TCS");  // works but awkward
    }
}
